"""Verdicts HE1 à HE6 (règles préinscrites) et résultat RE1 (précédent v1 et actuel v3). Idempotent."""
import sys, pathlib
sys.path.insert(0, str(pathlib.Path(__file__).resolve().parents[1] / "src"))
import tp2_journal as J
def last(i): return [e for e in J.entries() if e["id"] == i][-1]
F = "artifacts/results/v3/E_all_units.csv ; E_resume.csv ; E_HE1.csv ; E_HE2.csv ; E_HE3.csv ; E_HE4.csv ; E_HE5.csv ; E_conforme_units.csv"
NOTE_U = " Une unité (rotation 1, pli 0) avait été vue au test de fumée avant le calcul complet ; le verdict repose sur les 25 unités. Un premier calcul (E1) s'était arrêté sur une erreur d'indice : classes connues sans gabarit dans l'ensemble d'ajustement, voir la version E2 de scripts/v3_blockE.py."
def verdict(i, statut, preuve, note=""):
    if last(i)["statut"] == "préinscrite": J.add(i, "hypothese", last(i)["titre"], last(i)["texte"], justification="Verdict établi avec la règle de décision préinscrite (voir la version précédente).", statut=statut, preuve=preuve + "  Fichiers : " + F, note=note + NOTE_U)
verdict("HE1", "réfutée", "ECE moyen (25 unités) : aucune 0,179 ; température 0,169 (écart −0,010, p Holm 1,0) ; Platt 0,173 (−0,006, p Holm 1,0) ; isotonique 0,186 (+0,007) ; binning 0,190 (+0,011) ; vector scaling 0,226 (+0,046, p Holm 0,0009, PIRE) ; température sur classes cachées 0,323 (+0,144, p Holm 1e-5, PIRE). Aucune méthode ne réduit l'ECE de façon significative ; deux l'aggravent nettement.",
        "Constat à retenir : sous décalage de gabarits, calibrer sur environ 40 gabarits distincts n'améliore pas la calibration de façon fiable (la température ne gagne que 0,010, non significatif). Notebook v1 : ECE de 0,150 à 0,095 avec la température ; cet effet ne se retrouve pas avec ce protocole, qui est plus strict (jeu de calibration à gabarits distincts de l'entraînement comme du test). Variante « classes cachées » : T tombe au bord de la grille (T = 4), car maximiser l'AUROC de la confiance par un seul réglage de température n'a pas de maximum intérieur ; le modèle devient sous-confiant (ECE et NLL très mauvais) sans gain d'AUROC.")
verdict("HE2", "réfutée", "Vector scaling moins température : ECE +0,056 (0,226 contre 0,169), p = 1,4e-4 : écart supérieur à 0,01 et significatif.", "Un paramètre par classe, estimé sur une quarantaine de gabarits, surajuste les gabarits de calibration : cohérent avec Ovadia et al. (la calibration a posteriori se dégrade sous décalage).")
verdict("HE3", "confirmée", "Isotonique moins température : +0,016, p Holm 0,090 ; binning moins température : +0,021, p Holm 0,044 (binning significativement PIRE). Aucune des deux n'est inférieure à la température.", "Les méthodes non paramétriques surajustent le jeu de calibration.")
verdict("HE4", "réfutée", "Variation de l'AUROC d'inconnu du MSP contre « aucune » : température +0,003 (p = 0,15) ; Platt 0,000 ; vector scaling −0,044 (p = 0,15). La règle (« aucune méthode ne modifie l'AUROC de plus de 0,01 ») est violée par le vector scaling.", "Erreur dans la formulation de l'hypothèse : le vector scaling (une échelle et un biais PAR classe) ne préserve pas l'ordre des scores, contrairement à la température et à Platt, qui conservent l'ordre ; je l'avais rangé à tort parmi les méthodes monotones. Température et Platt respectent bien la règle (écart <= 0,003). Verdict « réfutée » au sens de la règle écrite ; à reformuler.")
verdict("HE5", "confirmée", "Température ajustée sur des logs des MÊMES gabarits que l'entraînement : ECE 0,296 contre 0,169 pour la température sur gabarits distincts (écart +0,127, p < 1e-6). Valeurs de T : inférieures à 1 (le modèle est rendu encore plus sûr de lui).", "Même fuite qu'au bloc A : un jeu de calibration qui ressemble à l'entraînement apprend une confiance trop optimiste.")
verdict("HE6", "confirmée", "Prédiction conforme visant 90 % : calibrée sur des gabarits distincts, couverture moyenne 0,899, au moins 0,87 dans 18 unités sur 25 ; calibrée sur les mêmes gabarits que l'entraînement, couverture moyenne 0,136, au moins 0,87 dans 0 unité. Les deux conditions de la règle sont satisfaites.", "Limite pratique : avec des gabarits distincts, les ensembles de prédiction sont énormes (11,9 classes en moyenne sur environ 24) : la garantie de couverture est tenue au prix d'une information très faible.")
if not J.exists("RE1"):
    J.add("RE1", "resultat", "Bloc E : calibration (précédent v1 et actuel v3)",
          "**Actuel (v3, 25 unités, ECE des classes connues du test, 15 bacs de même effectif) :** température 0,169 ; Platt 0,173 ; aucune 0,179 ; isotonique 0,186 ; binning 0,190 ; vector scaling 0,226 ; température sur mêmes gabarits 0,296 ; température sur classes cachées 0,323. Score de Brier : 0,201 (température) à 0,316. AUROC d'inconnu du MSP : 0,62 pour aucune, température et Platt. Conforme : couverture 0,899 (gabarits distincts) contre 0,136 (mêmes gabarits).  **Précédent (notebook v1, étape 9.6) :** TF-IDF, T = 1,62, ECE de 0,150 à 0,095 en validation, AUROC inchangé 0,603 ; encodeur : ECE 0,18 (validation) puis 0,35 (test) ; confiance annoncée 85 % pour 50 % de bonnes réponses.  Les deux séries sont conservées.",
          justification="Les deux séries s'accordent sur l'essentiel (la calibration par température ne change pas l'AUROC ; la confiance est trop élevée sous décalage de gabarits : ECE 0,18 ici sans calibration contre 0,15 en v1) mais pas sur le gain de la température (0,150 → 0,095 en v1 ; 0,179 → 0,169 non significatif ici). Le protocole v3, avec calibration sur gabarits distincts, mesure ce que v1 ne mesurait pas : l'instabilité de la température estimée sur peu de gabarits.", preuve=F)
print(J.render())
